from rules import has_cycle


def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))

    constraints = {}
    for name, bounds in roots.items():
        constraints.setdefault(name, []).append(tuple(bounds))

    best_score = None
    best_versions = None
    names = sorted(packages)

    def search(selected, required, graph):
        nonlocal best_score, best_versions

        pending = sorted(name for name in required if name not in selected)
        if not pending:
            if has_cycle(graph, selected):
                return
            score = tuple(selected.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = dict(selected)
            return

        name = pending[0]
        rows = packages.get(name, [])
        forbidden = set(blocked.get(name, []))
        pin = pins.get(name)
        choices = [
            row for row in rows
            if row['version'] not in forbidden
            and (pin is None or row['version'] == pin)
            and all(low <= row['version'] <= high
                    for low, high in required[name])
        ]
        choices.sort(key=lambda row: row['version'], reverse=True)

        for row in choices:
            version = row['version']
            next_selected = dict(selected)
            next_selected[name] = version
            next_required = {key: list(ranges) for key, ranges in required.items()}
            next_graph = {key: list(edges) for key, edges in graph.items()}
            next_graph.setdefault(name, [])
            valid = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                low, high = dep['min'], dep['max']
                next_required.setdefault(target, []).append((low, high))
                next_graph[name].append(target)
                if target in next_selected and not (low <= next_selected[target] <= high):
                    valid = False
                    break

            if valid:
                search(next_selected, next_required, next_graph)

    search({}, constraints, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def has_cycle(graph, selected):
    visiting = set()
    visited = set()

    def visit(name):
        if name in visiting:
            return True
        if name in visited:
            return False
        visiting.add(name)
        for target in graph.get(name, []):
            if target in selected and visit(target):
                return True
        visiting.remove(name)
        visited.add(name)
        return False

    return any(visit(name) for name in selected if name not in visited)
